	);
	bridge?.emitSystemLog?.(
		projectId,
		`[ERROR] Stage '${stage?.name || stage?.id}' failed on task #${task.id?.slice(0, 4)}: ${errorMsg}`,
		{ taskId, stageId: stage?.id, error: errorMsg, classification: classificationMeta },
