			taskId,
			fromStageId: stage?.id,
			targetStageId: fallbackTarget || task.currentStageId,
			error: errorMsg,
			projectName: projectId,
			classification: classificationMeta,
			...(compactionHintEffective ? { compactionHint: true } : {}),
		});

