 *   budget instead of hanging the gate to the stage timeout.
 * @example WORKSPACE_INSTALL_TIMEOUT_MS => 300000
 ***/
export const WORKSPACE_INSTALL_TIMEOUT_MS = 5 * 60 * 1000;

